import json, re

with open('batches/batch_0040.json', encoding='utf-8') as f:
    data = json.load(f)

def decode_mojibake(s):
    if not s:
        return s
    for enc_to in ['utf-8','cp932']:
        try:
            fixed = s.encode('latin1', errors='strict').decode(enc_to, errors='strict')
            return fixed
        except Exception:
            continue
    try:
        return s.encode('latin1', errors='replace').decode('utf-8', errors='replace')
    except Exception:
        return s

keywords = ['廃業','解散','閉鎖','閉店','停止','お断り','ご遠慮','拒否','受け付けておりません','営業を終了','事業を終了','maintenance','メンテナンス','休止']

for item in data:
    combined = decode_mojibake(item.get('title','')) + decode_mojibake(item.get('desc','')) + decode_mojibake(item.get('body',''))
    for kw in keywords:
        if kw in combined:
            print(item['idx'], item['name'], '->', kw)
